CREATE TABLE public.crocs (id serial PRIMARY KEY, tag text UNIQUE, pen_id text NOT NULL, line text NOT NULL, pen_slot integer NOT NULL, belly_cm numeric, condition_codes text[] NOT NULL DEFAULT '{}', inspection_date date NOT NULL, cull_schedule text, placement_date date, placement_belly_cm numeric, pen_since date);
GRANT SELECT ON public.crocs TO anon, authenticated; GRANT ALL ON public.crocs TO service_role;
ALTER TABLE public.crocs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read farm dataset" ON public.crocs FOR SELECT TO anon,authenticated USING (true);
CREATE TABLE public.inspections (id serial PRIMARY KEY, croc_id integer NOT NULL REFERENCES public.crocs(id) ON DELETE CASCADE, inspection_date date NOT NULL, belly_cm numeric, condition_codes text[] NOT NULL DEFAULT '{}', pen_id text, line text, pen_slot integer, UNIQUE(croc_id,inspection_date));
GRANT SELECT ON public.inspections TO anon,authenticated; GRANT ALL ON public.inspections TO service_role;
ALTER TABLE public.inspections ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read inspection history" ON public.inspections FOR SELECT TO anon,authenticated USING (true);
CREATE TABLE public.condition_codes (code text PRIMARY KEY, name text NOT NULL, color_var text NOT NULL DEFAULT '--ct-accent', is_live boolean NOT NULL DEFAULT true, is_hide boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.condition_codes TO anon,authenticated; GRANT ALL ON public.condition_codes TO service_role;
ALTER TABLE public.condition_codes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read conditions" ON public.condition_codes FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.croc_photos (id serial PRIMARY KEY, croc_id integer REFERENCES public.crocs(id) ON DELETE CASCADE, tag text, inspection_date date NOT NULL, photo_url text NOT NULL, storage_path text UNIQUE, belly_cm numeric, marks jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.croc_photos TO anon,authenticated; GRANT ALL ON public.croc_photos TO service_role;
ALTER TABLE public.croc_photos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read photo history" ON public.croc_photos FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.cull_records (id serial PRIMARY KEY, croc_id integer REFERENCES public.crocs(id) ON DELETE CASCADE, cull_date date NOT NULL, size_band_index integer, reason text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.cull_records TO anon,authenticated; GRANT ALL ON public.cull_records TO service_role;
ALTER TABLE public.cull_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read culls" ON public.cull_records FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.feed_records (id serial PRIMARY KEY, pen_id text NOT NULL, line text NOT NULL, cycle text NOT NULL, feed_kg numeric NOT NULL DEFAULT 0, croc_count integer, recorded_date date NOT NULL);
GRANT SELECT ON public.feed_records TO anon,authenticated; GRANT ALL ON public.feed_records TO service_role;
ALTER TABLE public.feed_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read feeds" ON public.feed_records FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.upload_logs (id serial PRIMARY KEY, filename text NOT NULL, record_count integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'success', warnings integer NOT NULL DEFAULT 0, uploaded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.upload_logs TO anon,authenticated; GRANT ALL ON public.upload_logs TO service_role;
ALTER TABLE public.upload_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read upload logs" ON public.upload_logs FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.capture_ingest_log (client_id text PRIMARY KEY, croc_id integer REFERENCES public.crocs(id) ON DELETE CASCADE, tag text, inspection_date date, received_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.capture_ingest_log TO service_role;
ALTER TABLE public.capture_ingest_log ENABLE ROW LEVEL SECURITY;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;
CREATE POLICY "Read farm photo files" ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='croc-photos');